import React, { useEffect, useState } from "react";
import axios from "axios";
import { LogOut } from "lucide-react";

const API_BASE_URL = "http://localhost:9091";

function UserShop({ token, onLogout }) {
  const [medicines, setMedicines] = useState([]);

  useEffect(() => {
    axios
      .get(`${API_BASE_URL}/api/user/medicines`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => setMedicines(res.data))
      .catch((err) => {
        console.error("User fetch failed:", err);
        setMedicines([
          { id: 1, name: "Mock User Item", price: 4.5, stockQuantity: 12 },
        ]);
      });
  }, [token]);

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-indigo-700">Pharmacy Shop</h2>
        <button
          onClick={onLogout}
          className="text-red-500 hover:text-red-700 flex items-center text-sm"
        >
          <LogOut className="w-4 h-4 mr-1" />
          Logout
        </button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {medicines.map((med) => (
          <div key={med.id} className="bg-white p-4 rounded-lg shadow">
            <h3 className="font-semibold">{med.name}</h3>
            <p className="text-gray-600 mb-2">₹{med.price?.toFixed(2)}</p>
            <p className="text-gray-500 text-sm">
              Stock: {med.stockQuantity}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default UserShop;
